            `:s==="kartu_peserta"?(()=>{Xe();const c=w.classes||[],u=w.rooms||[];let p=[...w.students||[]];if(window.kartuPesertaConfig.selectedClassIds&&window.kartuPesertaConfig.selectedClassIds.length>0?p=p.filter(x=>window.kartuPesertaConfig.selectedClassIds.includes(String(x.classId||x.class_id))):window.kartuPesertaConfig.filterClassId&&(p=p.filter(x=>String(x.classId||x.class_id)===String(window.kartuPesertaConfig.filterClassId))),window.kartuPesertaConfig.filterRoomId){const x=u.find(g=>String(g.id)===String(window.kartuPesertaConfig.filterRoomId));x&&(p=p.filter(g=>(x.members||[]).some(h=>String(h)===String(g.id))))}In(),$n(),Pn(window.kartuPesertaConfig.kop3),jn();const f=p.slice(0,4);return`
